<!doctype html><html lang="es"><head><meta charset="utf-8"><title>{{ $contract->contract_number }}</title><style>body{font-family:Arial,sans-serif;color:#111;padding:32px;max-width:800px;margin:auto}h1{color:#0b1f3a}.notice{border:2px solid #111;padding:14px;font-weight:bold;margin:24px 0}.overflow-x-auto{overflow-x:auto}table{width:100%;border-collapse:collapse}td{padding:8px;border-bottom:1px solid #bbb}@media print{button{display:none}}</style></head><body><h1>COOPERATIVA TIERRA BENDITA</h1><h2>RESUMEN DE REGISTRO</h2><div class="notice">NO CONSTITUYE COMPROBANTE DE PAGO</div><div class="overflow-x-auto"><table><tr><td>Contrato</td><td>{{ $contract->contract_number }}</td></tr><tr><td>Inversionista</td><td>{{ $contract->investor->full_name }}</td></tr><tr><td>CI</td><td>{{ $contract->investor->ci }}</td></tr><tr><td>Producto</td><td>{{ $contract->product_name_snapshot }}</td></tr><tr><td>Cantidad</td><td>{{ $contract->quantity }}</td></tr><tr><td>Precio unitario histórico</td><td>{{ $contract->currency }} {{ number_format((float)$contract->unit_price_snapshot,2) }}</td></tr><tr><td>Total de registro</td><td>{{ $contract->currency }} {{ number_format((float)$contract->total_amount,2) }}</td></tr><tr><td>Estado</td><td>{{ str($contract->status)->replace('_',' ')->headline() }}</td></tr></table></div><h3>Unidades registradas</h3><p>{{ $contract->units->pluck('code')->join(', ') ?: 'Pendientes de firma' }}</p><button onclick="window.print()">Imprimir</button></body></html>
